{
    Claims = new Dictionary<string, object> { ["sub"] = "u-42", ["name"] = "An" },
    SigningCredentials = new SigningCredentials(key, SecurityAlgorithms.HmacSha256)
});
var conn = new HubConnectionBuilder()
    .WithUrl(url + "/hub", o => o.AccessTokenProvider = () => Task.FromResult<string?>(token))
    .Build();
var received = 0;
conn.On<string>("Msg", _ => Interlocked.Increment(ref received));
await conn.StartAsync();
Console.WriteLine("UserIdentifier: " + await conn.InvokeAsync<string>("Who"));
var ctx = app.Services.GetRequiredService<IHubContext<MeHub>>();
await ctx.Clients.User("u-42").SendAsync("Msg", "hello");
await Task.Delay(300);
Console.WriteLine("tin toi u-42: " + received);
await conn.DisposeAsync();
await app.StopAsync();

[Authorize]
class MeHub : Hub
{
    public string Who() => Context.UserIdentifier ?? "(null)";
}

