await conn.DisposeAsync();
await app.StopAsync();

class Probe { public TaskCompletionSource<string> Error = new(); }

class JobHub(Probe probe) : Hub
{
    public Task StartJob()
    {
        _ = Task.Run(async () =>
        {
            await Task.Delay(300);
            try { await Clients.Caller.SendAsync("Done", "xong"); }
            catch (Exception ex) { probe.Error.TrySetResult(ex.GetType().Name); }
        });
        return Task.CompletedTask;
    }
}

